import time

from taf.sbts.oam.coam.admin.interfaces.admin_25r2 import SBTS25R2
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable
from taf.sbts.oam.coam.admin.utils import raise_value_error
from taf.sbts.oam.coam.admin.utils.validators import AnyObjectValidator, AllObjectsValidator, NoneObjectsValidator
from taf.sbts.oam.coam.admin.exceptions import ValidationError


class SBTS25R3(SBTS25R2):

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(SBTS25R3, self).__init__(api_client)

    def get_antenna_info_by_l1_iq_profile(self, profile, timeout=120, detailed_output=False):
        """
        Get antenna information by providing L1IQ profile.

        .. note::
            SUPPORTS CUSTOMER API ONLY

        :param str profile: One of ["UL_PROFILE_1", "UL_PROFILE_2", "UL_PROFILE_3", "DL_PROFILE_1", "UL_DL_PROFILE_1"].
        :param int timeout: Timeout for the operation, default set to 120 seconds.
        :param bool detailed_output: Return full request response when True, default set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getAntennaInfoByL1IQProfile.html
        """
        parameters = {'profile': profile}
        response = self._api_client.execute_customer_procedure(name="getAntennaInfoByL1IQProfile",
                                                               parameters=parameters,
                                                               timeout=timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def configure_uplane_l1_iq_data(self, capture_on_event, dl_nr_subcell_list=None, ul_nr_subcell_list=None,   # noqa: C901
                                    dl_lte_subcell_list=None, ul_lte_subcell_list=None,
                                    capture_on_event_bb_ru=None, capture_ru_list=None, buffer_cycle=None,
                                    capture_frame_offset=None, timeout=120, detailed_output=False, profile=None,
                                    **kwargs):
        """
        .. note::
            SUPPORTS CUSTOMER API ONLY

        Configure UPlaneL1IQData

        :param bool capture_on_event: (Mandatory) True or False.
                                      Since CB009514, configuration of "captureOnEvent" and "captureOnEventFromBBUAndRU" is now independent.
        :param list dl_nr_subcell_list: (Optional) schema: [{"nrcellDN": (mandatory),
                                                             "subcellId": [<0-255>] (mandatory)}]
                                        This parameter becomes REQUIRED when profile is configured as DL_PROFILE_1 | UL_DL_PROFILE_1.
                                        When UL_DL_PROFILE_1, only one cell can be configured and distName must be
                                        the same with the cell configured in ulNrSubcellList.
        :param list ul_nr_subcell_list: (Optional) schema: [{"nrcellDN": (mandatory),
                                                             "subcellId": [<0-255>] (mandatory)}]
                                        This parameter becomes REQUIRED when profile is configured as UL_PROFILE_1 | UL_PROFILE_2 | UL_PROFILE_3 | UL_DL_PROFILE_1.
                                        When UL_DL_PROFILE_1, only one cell can be configured and distName must be
                                        the same with the cell configured in dlNrSubcellList.
        :param list dl_lte_subcell_list: (Optional), but one of dlNrSubcellList | ulNrSubcellList |
                                         dlLteCellList | ulLteCellList must be configured, maxItems is 4,
                                         not applicable when "captureOnEventFromBBUAndRU" is True.
        :param list ul_lte_subcell_list: (Optional), but one of dlNrSubcellList | ulNrSubcellList |
                                         dlLteCellList | ulLteCellList must be configured, maxItems is 4,
                                         not applicable when "captureOnEventFromBBUAndRU" is True.
        :param bool capture_on_event_bb_ru: (Optional) True or False - default set to False.
                                            Since CB009514, configuration of "captureOnEventFromBBUAndRU" and "captureOnEvent" is now independent.
        :param list capture_ru_list: (Optional) schema: [{"targetRMOD": (mandatory),
                                                          "antennaList": [{
                                                                "polarization": (mandatory) enum string, ex. "MINUS_45"/"PLUS_45"/"PLUS_90"/"ZERO",
                                                                "antenna": (mandatory) array, ex. integer array<[1,2,3]> or string array<["ANT1"], ["ANT2"]>
                                                            }], (Optional) NOT ALLOWED if profile is configured as DL_PROFILE_1 | UL_DL_PROFILE_1.
                                                                If profile is UL_PROFILE_3, one of antennaList and groupId must be configured.
                                                          "groupId": [<1-65535>], (Optional) becomes REQUIRED if profile is configured as DL_PROFILE_1 | UL_DL_PROFILE_1.
                                                                                  If profile is UL_PROFILE_3, one of "antennaList" and "groupId" must be configured.
                                                          "captureActivityTimer": [<1-12>], (Optional) unit: hour, default 3}]
                                     Only applicable when "captureOnEventFromBBUAndRU" is True.
                                     If configured "minItem" is 1, all radios got from getUPlaneL1IQCaptureRMODAndAntennaList should be configured.
        :param string buffer_cycle: (Optional): "2frames"/"4frames"/"8frames"/"16frames"/"32frames"/"64frames"/"128frames"/
                                    "256frames"/"512frames"/"1024frames", only applicable when "captureOnEventFromBBUAndRU" is True, default "1024frames".
        :param int capture_frame_offset: (Optional), [<0-(bufferCycle(1024 by default)-1)>],
                                         only applicable when "captureOnEventFromBBUAndRU" is True, default set to 0.
        :param int timeout: (Optional) Timeout for the operation, defaults to 120 seconds.
        :param bool detailed_output: Return full request response when True, default set to False.
        :param str profile: (Optional) Only applicable when "captureOnEventFromBBUAndRU" is True.
                            Since CB009514 and SBTS25R3, "captureMode" parameter has been replaced with "profile".
                            Example: "UL_PROFILE_1"/"UL_PROFILE_2"/"UL_PROFILE_3"/"DL_PROFILE_1"/"UL_DL_PROFILE_1".
                            Each profile represents different captureMode (FD, TD, FD_POSTBF):
                                - UL_PROFILE_1: [UL][FD][Event/Blind][7-2e]PUSCH/PUCCH/SRS issues debugging
                                - UL_PROFILE_2: [UL][FD_POSTBF][Event/Blind][7-2e]PUSCH/SRS issues debugging, except beamforming function of PUSCH
                                - UL_PROFILE_3: [UL][TD][Event][7-2a/7-2e]Timing issues debugging
                                - DL_PROFILE_1: [DL][FD_POSTBF][Event/Blind][7-2e]DL BLER or DL Throughput degradation issues debugging
                                - UL_DL_PROFILE_1: [UL/DL][FD_POSTBF][Event][7-2e]Sleeping-Cell issues detected by Msg3 failure
                            When "captureOnEventFromBBUAndRU" = True and "captureOnEvent" = True, Event type profiles are allowed.
                            When "captureOnEventFromBBUAndRU" = True and "captureOnEvent" = False, Blind type profiles are allowed.
        :raises DataNotAvailable: If Configure UPlaneL1IQData status has not been provided by M-Plane.
        :raises KeyError: If none of dlNrSubcellList | ulNrSubcellList | dlLteCellList | ulLteCellList is provided.
        :raises ValueError: If none of dlNrSubcellList | ulNrSubcellList | dlLteCellList | ulLteCellList is list object.
        :return Union[str,dict]: Status of the operation or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-configureUPlaneL1IQData.html
        """  # noqa: E501

        params = [dl_nr_subcell_list, ul_nr_subcell_list, dl_lte_subcell_list, ul_lte_subcell_list]

        if not any(params):
            msg = "One of dl_nr_subcell_list | ul_nr_subcell_list | dl_lte_subcell_list | ul_lte_subcell_list " \
                  "must be configured"
            raise KeyError(msg)

        params = [item for item in params if isinstance(item, list)]
        if not params:
            msg = "Params dl_nr_subcell_list | ul_nr_subcell_list | dl_lte_subcell_list | ul_lte_subcell_list must be " \
                  "passed as lists"
            raise ValueError(msg)

        if capture_on_event_bb_ru:
            temp_params = [item for item in params if isinstance(item, list) and item not in (dl_nr_subcell_list, ul_nr_subcell_list)]
            try:
                if any(temp_params):
                    msg = "dl_lte_subcell_list | ul_lte_subcell_list are not applicable when " \
                          "capture_on_event_bb_ru is set"
                    raise KeyError(msg)
            except ValueError:
                pass

            if not isinstance(capture_ru_list, list):
                msg = "Param capture_ru_list must be passed as a list"
                raise ValueError(msg)

        if profile:
            if profile not in ["UL_PROFILE_1", "UL_PROFILE_2", "UL_PROFILE_3", "DL_PROFILE_1", "UL_DL_PROFILE_1"]:
                raise_value_error(param="profile",
                                  value=str(profile),
                                  subpage="tutorial-configureUPlaneL1IQData.html")

        parameters = {"dlNrSubcellList": dl_nr_subcell_list,
                      "ulNrSubcellList": ul_nr_subcell_list,
                      "dlLteCellList": dl_lte_subcell_list,
                      "ulLteCellList": ul_lte_subcell_list,
                      "captureOnEvent": capture_on_event,
                      "captureOnEventFromBBUAndRU": capture_on_event_bb_ru,
                      "captureRUList": capture_ru_list,
                      "bufferCycle": buffer_cycle,
                      "captureFrameOffset": capture_frame_offset,
                      "profile": profile}

        parameters = {k: v for k, v in parameters.items() if v is not None}

        response = self._api_client.execute_customer_procedure(name="configureUPlaneL1IQData",
                                                               parameters=parameters,
                                                               timeout=timeout)
        if response is None:
            raise DataNotAvailable("Configure UPlaneL1IQData status has not been provided by M-Plane.")
        return response if detailed_output else response.get(self._provided_content.request_message)

    def get_ids_for_all(self, class_name, timeout=10, search_for_iot_cells="LNCEL"):
        """
        Get IDs for all items of given class.

        :param str class_name: "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL", "BBMOD",
                                  "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "NRADJGNB", "CARRIERGROUPC", "FHS".
        :param int timeout: Time to wait for positive procedure result.
        :param Literal["LNCEL", "NRCEL", "all"] | bool search_for_iot_cells:
            > If "LNCEL" given: do the "deep search" for IoT cells under "LNCEL" objects.
            > If "NRCEL" given: do it only for IoT cells under "NRCEL" objects.
            > If "all" specified: do it for both (and others in the future should there be a need for that).
            > If False - do not search at all.
            > If True - same as "all".
        :return list: List of distnames to the connected entity id

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getParametersForAllEntities.html
        """
        items = self.get_parameters_for_all(class_name, timeout)
        result = [item["id"] for item in items]

        if class_name == "LNCEL":
            if search_for_iot_cells == 'LNCEL':
                lte_iot_cells = [item["nbIoTCell"] for item in items if item.get("nbIoTCell")]
                lte_iot_cells_dn = [elem['distName'] for elem in lte_iot_cells]
                result += lte_iot_cells_dn

                return result

            if search_for_iot_cells == 'NRCEL':
                nr_response = self.get_parameters_for_all("NRCEL", timeout)
                nr_iot_cells = [item["nbIoTCell"] for item in nr_response if item.get("nbIoTCell")]
                nr_iot_cells_dn = [elem['distName'] for elem in nr_iot_cells]
                result += nr_iot_cells_dn

                return result

            if search_for_iot_cells == 'all' or search_for_iot_cells is True:
                lte_iot_cells = [item["nbIoTCell"] for item in items if item.get("nbIoTCell")]
                lte_iot_cells_dn = [elem['distName'] for elem in lte_iot_cells]
                result += lte_iot_cells_dn

                nr_response = self.get_parameters_for_all("NRCEL", timeout)
                nr_iot_cells = [item["nbIoTCell"] for item in nr_response if item.get("nbIoTCell")]
                nr_iot_cells_dn = [elem['distName'] for elem in nr_iot_cells]
                result += nr_iot_cells_dn

                return result

        return result

    def _subscribe_all_parameters(self, class_name, validator, parameters=None, timeout=10, search_for_iot_cells=False):
        """
        Perform subscription for subscribeForAllParameters CLI request and perform validation.

        :param string class_name: One of "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL",
                                  "BBMOD", "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS".
        :param validator ObjectValidator: Validtor see taf.sbts.oam.coam.admin.utils.validators
        :param string parameters: Requierd item parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param int timeout: Time to wait for matching items.
        :param bool search_for_iot_cells: If set to True and class_name=LNCEL,
         it will search for LTE IOT cells nested within NR cells. False by default.

        More info at https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-subscribeForAllParameters.html
        """
        class_name = class_name.upper()
        if class_name not in ("RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL", "BBMOD",
                              "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                              "CABINET", "CARRIERGROUPC", "FHS"):
            raise_value_error(param="class_name",
                              value=str(class_name),
                              subpage="tutorial-subscribeForAllParameters.html")

        if class_name == 'LNCEL' and search_for_iot_cells:
            result = self._validate_iot_cells(validator, parameters, timeout)

        else:
            result = self._api_client.execute_infomodel_subscription(
                "subscribeForAllParameters", {"className": class_name}, validator(parameters), timeout)

        return result

    def _wait_for_valid_data(self, fetch_func, class_name, timeout, validator_instance, interval=5):
        """Retry fetching data until timeout expires or valid data is returned"""
        timeout = int(timeout)
        start = time.time()
        while time.time() - start < timeout:
            data = fetch_func(class_name, timeout)
            if data and validator_instance.check(data):
                return data
            time.sleep(interval)
        return []

    def _validate_iot_cells(self, validator, parameters, timeout):                 # noqa: C901
        """Validates whether iot cells meet given criteria"""
        result = []
        partial_check = []
        validator_instance = validator(parameters)

        lte_cells = self._wait_for_valid_data(self.get_parameters_for_all, "LNCEL", timeout, validator_instance)
        if lte_cells:
            regular_lte_check = validator_instance.check(lte_cells)
            partial_check.append(regular_lte_check)
            if regular_lte_check:
                result += lte_cells

            lte_iot_cells = [item["nbIoTCell"] for item in lte_cells if item.get("nbIoTCell", {}) is not None]
            if lte_iot_cells:
                lte_state_infos = [cell.get("stateInfo") for cell in lte_iot_cells]
                lte_iot_check = validator_instance.check(lte_state_infos)
                partial_check.append(lte_iot_check)
                if lte_iot_check:
                    result += lte_iot_cells

            if all(check is True for check in partial_check):
                return result

        nr_cells = self._wait_for_valid_data(self.get_parameters_for_all, "NRCEL", timeout, validator_instance)
        if nr_cells:
            nr_iot_cells = [item["nbIoTCell"] for item in nr_cells if item.get("nbIoTCell", {}) is not None]
            if nr_iot_cells:
                nr_state_infos = [cell.get("stateInfo") for cell in nr_iot_cells]
                nr_iot_check = validator_instance.check(nr_state_infos)
                partial_check.append(nr_iot_check)
                if nr_iot_check:
                    result += nr_iot_cells

        if not lte_cells and not nr_cells:
            raise TimeoutError("No LTE or NR cells fetched within the timeout.")
        if any(check is False for check in partial_check if check is not None):
            raise ValidationError("Cell(s) do(es) not meet given criteria.")
        if not result:
            raise TimeoutError("No valid cells found within the timeout.")

        return result

    def check_if_any(self, class_name, parameters=None, timeout=10, search_for_iot_cells=False):
        """
        Assert that any item of given class exists and matches given parameters.

        :param string class_name: One of "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL",
                                  "BBMOD", "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS".
        :param string parameters: Requierd item parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param int timeout: Time to wait for matching item.
        :param bool search_for_iot_cells: If set to True and class_name=LNCEL,
         it will search for LTE IOT cells nested within NR cells. False by default.

        :return dict: dict with class name info

        """
        return self._subscribe_all_parameters(class_name, AnyObjectValidator, parameters, timeout, search_for_iot_cells)

    def check_if_every(self, class_name, parameters, timeout=10, search_for_iot_cells=False):
        """
        Assert that every item of given class matches given parameters.

        :param string class_name: One of "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL",
                                  "BBMOD", "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS".
        :param string parameters: Requierd item parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param int timeout: Time to wait for matching items.
        :param bool search_for_iot_cells: If set to True and class_name=LNCEL,
         it will search for LTE IOT cells nested within NR cells. False by default.

        :return dict: dict with class name info

        """
        return self._subscribe_all_parameters(class_name, AllObjectsValidator, parameters, timeout, search_for_iot_cells)

    def check_if_no(self, class_name, parameters=None, timeout=10, search_for_iot_cells=False):
        """
        Assert that no item of given class exists or matches given parameters.

        :param string class_name: One of "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL",
                                  "BBMOD", "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS".
        :param string parameters: Requierd item parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param int timeout: Time to wait for matching items.
        :param bool search_for_iot_cells: If set to True and class_name=LNCEL,
         it will search for LTE IOT cells nested within NR cells. False by default.

        :return dict: dict with class name info
        """
        return self._subscribe_all_parameters(class_name, NoneObjectsValidator, parameters, timeout, search_for_iot_cells)
